 "content": "from math import gcd
from functools import reduce


def transform(grid):
    """Rotate the sparse color key clockwise and use it to recolor tiled 8s."""
    h, w = len(grid), len(grid[0])
    eight = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 8)]
    if not eight or not markers:
        return [row[:] for row in grid]

    # Repeated horizontal/vertical run lengths reveal the square tile scale.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 8:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == 8:
                c += 1
            runs.append(c - start)
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 8:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == 8:
                r += 1
            runs.append(r - start)
    scale = reduce(gcd, runs)

    r0, r1 = min(r for r, _ in markers), max(r for r, _ in markers)
    c0, c1 = min(c for _, c in markers), max(c for _, c in markers)
    key = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]
    for r, c in markers:
        key[r - r0][c - c0] = grid[r][c]
    rotated = [list(row) for row in zip(*key[::-1])]

    top, left = min(r for r, _ in eight), min(c for _, c in eight)
    rows, cols = len(rotated), len(rotated[0])
    out = [row[:] for row in grid]
    for tr in range(rows):
        for tc in range(cols):
            color = rotated[tr][tc]
            if not color:
                continue
            rr, cc = top + tr * scale, left + tc * scale
            # Color only complete 8-tiles; unrelated cells are left untouched.
            if rr + scale <= h and cc + scale <= w and all(
                grid[y][x] == 8
                for y in range(rr, rr + scale)
                for x in range(cc, cc + scale)
            ):
                for y in range(rr, rr + scale):
                    for x in range(cc, cc + scale):
                        out[y][x] = color
    return out
